import type { HTMLAttributes, ReactNode } from 'react'
import { cn } from '@/lib/utils'
import { responsiveStyle, responsiveCSS, type Responsive } from '@/lib/responsive'
export function Grid({
  minWidth = 180,
  gap = 16,
  className,
  style,
  ...props
}: HTMLAttributes<HTMLDivElement> & { minWidth?: number; gap?: number }) {
  return (
    <div
      className={cn('grid', className)}
      style={{
        gridTemplateColumns: `repeat(auto-fit,minmax(min(${minWidth}px,100%),1fr))`,
        gap,
        ...style,
      }}
      {...props}
    />
  )
}
export function Row({
  gutter = 16,
  children,
  className,
  style,
  ...props
}: HTMLAttributes<HTMLDivElement> & { gutter?: number | [number, number] }) {
  const [x, y] = Array.isArray(gutter) ? gutter : [gutter, gutter]
  return (
    <div
      className={cn('flex flex-wrap', className)}
      style={
        {
          marginInline: -x / 2,
          rowGap: y,
          '--grid-gutter': `${x}px`,
          ...style,
        } as React.CSSProperties
      }
      {...props}
    >
      {children}
    </div>
  )
}
export interface ColProps extends HTMLAttributes<HTMLDivElement> {
  span?: Responsive<number>
  offset?: Responsive<number>
  order?: Responsive<number>
}
export function Col({
  span = 24,
  offset = 0,
  order = 0,
  style,
  className,
  children,
  ...props
}: ColProps) {
  return (
    <div
      className={cn('ergon-col min-w-0', className)}
      style={{
        ...responsiveStyle(span, 'span'),
        ...responsiveStyle(offset, 'offset'),
        ...responsiveStyle(order, 'order'),
        paddingInline: 'calc(var(--grid-gutter,16px) / 2)',
        ...style,
      }}
      {...props}
    >
      <style>{responsiveCSS}</style>
      {children}
    </div>
  )
}

import { clsx, type ClassValue } from 'clsx'
import { twMerge } from 'tailwind-merge'
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

import type { CSSProperties } from 'react'
export const breakpoints = { xs: 0, sm: 640, md: 768, lg: 1024, xl: 1280, '2xl': 1536 } as const
export type Breakpoint = keyof typeof breakpoints
export type Responsive<T> = T | Partial<Record<Breakpoint, T>>
export function responsiveStyle<T>(value: Responsive<T> | undefined, name: string): CSSProperties {
  if (value === undefined) return {}
  const values = typeof value === 'object' && value !== null ? value : { xs: value }
  return Object.fromEntries(
    Object.entries(values).map(([key, v]) => [`--${name}-${key}`, v]),
  ) as CSSProperties
}
export const responsiveCSS = Object.entries(breakpoints)
  .map(([point, min], index) => {
    const fallback = (name: string, initial: string) =>
      Object.keys(breakpoints)
        .slice(0, index + 1)
        .reduce((result, key) => `var(--${name}-${key},${result})`, initial)
    return `@media(min-width:${min}px){.ergon-col{width:calc(${fallback('span', '24')} / 24 * 100%);margin-inline-start:calc(${fallback('offset', '0')} / 24 * 100%);order:${fallback('order', '0')}}.ergon-flex{gap:${fallback('gap', '12px')};flex-direction:${fallback('direction', 'row')}}}`
  })
  .join('')
